-- WAHY LAB SOLUTIONS: TECHNOLOGICAL SKILL GAP PROJECT
-- Complete MySQL script: table + 100 INSERT records + analysis queries
CREATE DATABASE IF NOT EXISTS wahy_skill_gap;
USE wahy_skill_gap;

DROP TABLE IF EXISTS Wahy_Employee_Skill_Gap;
CREATE TABLE Wahy_Employee_Skill_Gap (
    `Respondent_ID` VARCHAR(10) PRIMARY KEY,
    `Age` VARCHAR(30),
    `Gender` TEXT,
    `Designation` TEXT,
    `Department` TEXT,
    `Association_with_Wahy` TEXT,
    `Q6_Technical_skills_required` TEXT,
    `Q7_Adapt_to_new_technologies` TEXT,
    `Q8_Adequate_technical_training` TEXT,
    `Q9_Mentor_technical_guidance` TEXT,
    `Q10_Opportunities_to_improve_skills` TEXT,
    `Q11_Confidence_using_software_tools` TEXT,
    `Q12_Need_additional_technical_training` TEXT,
    `Q13_Training_applies_knowledge_to_real_projects` TEXT,
    `Q14_Complete_tasks_on_time` TEXT,
    `Q15_Work_quality_meets_expectations` TEXT,
    `Q16_Solve_technical_problems_independently` TEXT,
    `Q17_Collaborate_effectively` TEXT,
    `Q18_Adapt_to_project_changes` TEXT,
    `Q19_Technical_skills_influence_performance` TEXT,
    `Q20_Training_improved_performance` TEXT,
    `Q21_Satisfaction_with_work_performance` TEXT,
    `Q22_Current_technologies` TEXT,
    `Q23_Additional_training_needed` TEXT,
    `Q24_Most_effective_learning_method` TEXT,
    `Q25_Satisfaction_with_Wahy_training` TEXT,
    `Q26_Challenges` TEXT,
    `Q27_Suggestions` TEXT
);

