-- BASIC ANALYSIS QUERIES
SELECT COUNT(*) AS Total_Respondents FROM Wahy_Employee_Skill_Gap;
SELECT Gender, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Gender;
SELECT Designation, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Designation;
SELECT Department, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Department ORDER BY No_of_Respondents DESC;
SELECT Age, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Age ORDER BY Age;
SELECT Q7_Adapt_to_new_technologies, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Q7_Adapt_to_new_technologies;
SELECT Q8_Adequate_technical_training, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Q8_Adequate_technical_training;
SELECT Q9_Mentor_technical_guidance, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Q9_Mentor_technical_guidance;
SELECT Q11_Confidence_using_software_tools, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Q11_Confidence_using_software_tools;
SELECT Q12_Need_additional_technical_training, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Q12_Need_additional_technical_training;
SELECT Q24_Most_effective_learning_method, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Q24_Most_effective_learning_method;
SELECT Q25_Satisfaction_with_Wahy_training, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Q25_Satisfaction_with_Wahy_training;
-- EMPLOYEE / INTERN GROUPING (Intern only = Intern; all other designations = Employee)
SELECT CASE WHEN Designation='Intern' THEN 'Intern' ELSE 'Employee' END AS Employee_Status, COUNT(*) AS No_of_Respondents FROM Wahy_Employee_Skill_Gap GROUP BY Employee_Status;
-- TECHNOLOGICAL SKILL SCORE
SELECT Respondent_ID,
ROUND((CASE Q6_Technical_skills_required WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END +
CASE Q7_Adapt_to_new_technologies WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END +
CASE Q11_Confidence_using_software_tools WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END)/3,2) AS Technological_Skill_Score
FROM Wahy_Employee_Skill_Gap;
-- OVERALL TECHNOLOGICAL SKILL MEAN
SELECT ROUND(AVG((
CASE Q6_Technical_skills_required WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END +
CASE Q7_Adapt_to_new_technologies WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END +
CASE Q11_Confidence_using_software_tools WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END)/3),2) AS Technological_Skill_Mean
FROM Wahy_Employee_Skill_Gap;
-- TRAINING/SUPPORT MEAN (Q12 reverse-coded: 6 - original score)
SELECT ROUND(AVG((
CASE Q8_Adequate_technical_training WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END +
CASE Q9_Mentor_technical_guidance WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END +
CASE Q10_Opportunities_to_improve_skills WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END +
(6-CASE Q12_Need_additional_technical_training WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END) +
CASE Q13_Training_applies_knowledge_to_real_projects WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END +
CASE Q20_Training_improved_performance WHEN 'Strongly disagree' THEN 1 WHEN 'Disagree' THEN 2 WHEN 'Neutral' THEN 3 WHEN 'Agree' THEN 4 WHEN 'Strongly agree' THEN 5 END)/6),2) AS Training_Support_Mean
FROM Wahy_Employee_Skill_Gap;